<script>
 import { onMount } from 'svelte';
 let popular=[], airing=[], upcoming=[], anime=[]; let q=''; let loading=true; let error=''; let active='All';
 const genres=['All','Action','Adventure','Comedy','Fantasy','Romance','Sci-Fi','Drama','Mystery'];
 async function api(url){const r=await fetch(url);if(!r.ok)throw Error();return (await r.json()).data||[]}
 async function load(){loading=true;error='';try{[popular,airing,upcoming]=await Promise.all([api('https://api.jikan.moe/v4/top/anime?filter=bypopularity&limit=12'),api('https://api.jikan.moe/v4/top/anime?filter=airing&limit=12'),api('https://api.jikan.moe/v4/top/anime?filter=upcoming&limit=12')]);anime=popular}catch(e){error='Anime service is temporarily unavailable. Please retry.'}finally{loading=false}}
 async function search(){if(!q.trim())return load();loading=true;try{anime=await api(`https://api.jikan.moe/v4/anime?q=${encodeURIComponent(q)}&limit=24&sfw=true`)}catch(e){error='Search failed. Please retry.'}finally{loading=false}}
 async function genre(g){active=g;if(g==='All'){anime=popular;return}loading=true;try{anime=await api(`https://api.jikan.moe/v4/anime?genres=${encodeURIComponent(g)}&limit=24&sfw=true`)}catch(e){error='Could not load this genre.'}finally{loading=false}}
 onMount(load);
</script>
<svelte:head><title>AniVerse — Anime Discovery</title><meta name="description" content="Discover popular, airing and upcoming anime on AniVerse."/></svelte:head>
<div class="app"><header><a class="logo" href="/"><b>A</b><span>Ani<em>Verse</em></span></a><nav><a class="active" href="/">Home</a><a href="#popular">Popular</a><a href="#airing">Airing</a><a href="#upcoming">Upcoming</a></nav><form on:submit|preventDefault={search}><span>⌕</span><input bind:value={q} placeholder="Search anime..." aria-label="Search anime"/><button>Search</button></form></header>
<section class="hero"><div class="heroText"><small>YOUR NEXT OBSESSION STARTS HERE</small><h1>Find your next<br/><i>anime adventure.</i></h1><p>Discover popular series, currently airing shows, upcoming releases and hidden gems — all in one clean anime hub.</p><div><a class="cta" href="#popular">Explore Anime →</a><a class="ghost" href="#genres">Browse Genres</a></div></div><div class="glow"></div><div class="gridbg"></div></section>
<section class="genres" id="genres">{#each genres as g}<button class:chosen={active===g} on:click={()=>genre(g)}>{g}</button>{/each}</section>
{#if error}<div class="error">{error}<button on:click={load}>Retry</button></div>{/if}
{#if loading}<main><div class="cards">{#each Array(12) as _}<div class="skeleton"></div>{/each}</div></main>{:else}
<section class="section" id="popular"><div class="heading"><div><small>TOP PICKS</small><h2>Popular Anime</h2></div><span>{anime.length} titles</span></div><div class="cards">{#each anime as a}<a class="card" href={`/anime/${a.mal_id}`}><div class="poster"><img src={a.images?.jpg?.large_image_url||a.images?.jpg?.image_url} alt={a.title} loading="lazy"/><label>★ {a.score??'N/A'}</label></div><h3>{a.title}</h3><p>{a.type||'Anime'} · {a.episodes||'?'} eps</p></a>{/each}</div></section>
<section class="section" id="airing"><div class="heading"><div><small>WATCH NOW</small><h2>Top Airing</h2></div></div><div class="cards">{#each airing as a}<a class="card" href={`/anime/${a.mal_id}`}><div class="poster"><img src={a.images?.jpg?.large_image_url||a.images?.jpg?.image_url} alt={a.title} loading="lazy"/><label>● AIRING</label></div><h3>{a.title}</h3><p>Currently airing · ★ {a.score??'N/A'}</p></a>{/each}</div></section>
<section class="section" id="upcoming"><div class="heading"><div><small>COMING SOON</small><h2>Upcoming Anime</h2></div></div><div class="cards">{#each upcoming as a}<a class="card" href={`/anime/${a.mal_id}`}><div class="poster"><img src={a.images?.jpg?.large_image_url||a.images?.jpg?.image_url} alt={a.title} loading="lazy"/><label>UPCOMING</label></div><h3>{a.title}</h3><p>{a.type||'Anime'} · Score {a.score??'N/A'}</p></a>{/each}</div></section>
{/if}<footer><strong>Ⓐ AniVerse</strong><span>Anime discovery built for fans.</span><small>Playback is intended for licensed or officially provided sources.</small></footer></div>
<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#08090d;color:#f5f5f7;font-family:Inter,system-ui,sans-serif}:global(a){color:inherit;text-decoration:none}button,input{font:inherit}.app{min-height:100vh;background:radial-gradient(circle at 75% 10%,#281b4d33,transparent 35%),#08090d}header{height:76px;display:flex;align-items:center;gap:36px;padding:0 5vw;border-bottom:1px solid #ffffff0c;background:#08090dcc;backdrop-filter:blur(18px);position:sticky;top:0;z-index:10}.logo{display:flex;align-items:center;gap:10px;font-size:20px;font-weight:800}.logo b{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:linear-gradient(135deg,#a58cff,#6546dc)}.logo em{color:#9b7cff;font-style:normal}nav{display:flex;gap:22px;color:#858793;font-size:13px}nav .active,nav a:hover{color:#fff}form{margin-left:auto;display:flex;align-items:center;width:min(360px,34vw);background:#111218;border:1px solid #242630;border-radius:11px;padding:4px 5px 4px 12px}form span{color:#777;font-size:20px}input{flex:1;min-width:0;border:0;outline:0;background:transparent;color:white;padding:9px}form button{border:0;border-radius:8px;background:#272332;color:#ddd5ff;padding:8px 12px;cursor:pointer}.hero{min-height:510px;display:flex;align-items:center;padding:70px 8vw;position:relative;overflow:hidden;border-bottom:1px solid #ffffff08}.heroText{position:relative;z-index:2;max-width:700px}.hero small,.section small{color:#9b7cff;font-weight:800;letter-spacing:2px;font-size:11px}h1{font-size:clamp(45px,6vw,78px);line-height:.98;letter-spacing:-4px;margin:15px 0}h1 i{color:#9b7cff;font-style:normal}.hero p{color:#9698a5;line-height:1.7;max-width:540px;margin:0 0 25px}.cta,.ghost{display:inline-block;padding:13px 18px;border-radius:10px;font-weight:700;margin-right:9px}.cta{background:#8d6cf1;box-shadow:0 10px 30px #8d6cf133}.ghost{border:1px solid #292b34;background:#111218;color:#ccc}.glow{position:absolute;right:7%;width:430px;height:430px;border-radius:50%;background:radial-gradient(circle,#8b63ff4d,transparent 65%)}.gridbg{position:absolute;inset:0;opacity:.12;background-image:linear-gradient(#fff 1px,transparent 1px),linear-gradient(90deg,#fff 1px,transparent 1px);background-size:70px 70px;mask-image:linear-gradient(to right,transparent,black 55%,transparent)}.genres{display:flex;gap:8px;padding:20px 5vw;overflow:auto;border-bottom:1px solid #ffffff0b}.genres button{border:1px solid #292b34;background:#101117;color:#888b97;padding:9px 15px;border-radius:999px;white-space:nowrap;cursor:pointer}.genres button:hover,.genres button.chosen{border-color:#6d54bb;background:#1c1830;color:#c9bcff}.section{padding:55px 5vw 20px}.heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:25px}.heading h2{font-size:30px;letter-spacing:-1.5px;margin:8px 0 0}.heading>span{color:#686a76;font-size:13px}.cards{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:20px}.card{min-width:0}.poster{aspect-ratio:2/3;overflow:hidden;border-radius:13px;background:#14151b;border:1px solid #ffffff0d;position:relative}.poster img{width:100%;height:100%;object-fit:cover;display:block;transition:.35s}.card:hover img{transform:scale(1.045)}.poster label{position:absolute;top:8px;left:8px;padding:5px 7px;border-radius:7px;background:#08090dcc;font-size:10px;color:#f2d98a}.card h3{font-size:14px;margin:10px 2px 5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card p{font-size:11px;color:#686a76;margin:0 2px}.skeleton{aspect-ratio:2/3;border-radius:13px;background:linear-gradient(100deg,#121319 25%,#1b1c23 40%,#121319 55%);background-size:300% 100%;animation:shimmer 1.4s infinite}@keyframes shimmer{to{background-position:-200% 0}}.error{margin:25px 5vw;padding:20px;border:1px solid #292a33;border-radius:13px;color:#aaa}.error button{margin-left:10px;border:0;border-radius:8px;padding:8px 12px;background:#8d6cf1;color:white}footer{margin-top:55px;padding:30px 5vw;border-top:1px solid #ffffff0b;display:flex;gap:25px;align-items:center;color:#666975;font-size:12px}footer strong{font-size:18px;color:#ddd}footer span{flex:1}@media(max-width:1100px){.cards{grid-template-columns:repeat(4,minmax(0,1fr))}nav{display:none}}@media(max-width:700px){header{padding:0 18px;gap:15px}form{width:auto;flex:1}form button{display:none}.hero{padding:55px 22px;min-height:440px}h1{letter-spacing:-2.5px}.section{padding:45px 18px 10px}.genres{padding:16px 18px}.cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}footer{flex-direction:column;align-items:flex-start}}
</style>